function App() {
  // Simulating what the browser can see:
  const clientEnv = { NEXT_PUBLIC_API_URL: 'https://api.example.com' };
  const publicVal = clientEnv.NEXT_PUBLIC_API_URL;        // available in browser
  const secretVal = clientEnv.DATABASE_URL;               // undefined on client
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Client-visible env</h3>
      <p>NEXT_PUBLIC_API_URL: <b>{String(publicVal)}</b></p>
      <p>DATABASE_URL: <b>{String(secretVal)}</b> (server-only -> undefined here)</p>
    </div>
  );
}

