function App() {
  const verdicts = {
    'Analytics site ID': 'PUBLIC — NEXT_PUBLIC_ANALYTICS_ID (needed in the browser)',
    'Database password': 'SERVER-ONLY — secret, never NEXT_PUBLIC_',
    'Public API base URL': 'PUBLIC — NEXT_PUBLIC_API_URL (used by client fetches)',
    'Auth signing secret': 'SERVER-ONLY — secret, never NEXT_PUBLIC_',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(verdicts).map(([k, v]) => <li key={k}><b>{k}:</b> {v}</li>)}
    </ul>
  );
}

