function App() {
  // Illustrative fix — secret stays server-only:
  const lines = [
    "# .env.local (gitignored)",
    "STRIPE_SECRET_KEY=sk_live_...   # no prefix -> server-only",
    "",
    "// app/api/checkout/route.ts (server):",
    "const key = process.env.STRIPE_SECRET_KEY; // never sent to the browser",
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {lines.join('\n')}
    </pre>
  );
}

